"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["37954"],{94674(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>l});var i=JSON.parse('{"id":"identity/hewillbeback","title":"","description":"Qingming Festival has come around again. In the past I was never particularly sensitive to this day, because death still felt far away from us \u2014 and matters too distant are things one is reluctant to contemplate prematurely.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/identity/hewillbeback.md","sourceDirName":"identity","slug":"/identity/hewillbeback","permalink":"/en/identity/hewillbeback","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"hewillbeback","title":"","hide_table_of_contents":true,"sidebar_label":"He has gone wandering, and will return again (Fund Analysis)"},"sidebar":"identitySidebar","previous":{"title":"\\"Fund Analysis\\" article from November 17, 2008","permalink":"/en/identity/fundanalysis"},"next":{"title":"Fund Analysis farewell letter","permalink":"/en/identity/fundanalysisfarewell"}}'),a=t(74848),o=t(28453);let s={id:"hewillbeback",title:"",hide_table_of_contents:!0,sidebar_label:"He has gone wandering, and will return again (Fund Analysis)"},r="He Has Gone Wandering \u2014 He Will Come Back (Fund Analysis)",l={},h=[];function d(e){let n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"he-has-gone-wandering--he-will-come-back-fund-analysis",children:"He Has Gone Wandering \u2014 He Will Come Back (Fund Analysis)"})}),"\n",(0,a.jsx)(n.p,{children:"Qingming Festival has come around again. In the past I was never particularly sensitive to this day, because death still felt far away from us \u2014 and matters too distant are things one is reluctant to contemplate prematurely."}),"\n",(0,a.jsx)(n.p,{children:"As the years accumulate, especially as peers and even younger friends depart one after another, a lingering melancholy and heartache forces one to reflect."}),"\n",(0,a.jsx)(n.p,{children:"The ultimate destination of life can only be one, and no one can escape it. Yet until that moment arrives, no one engages in deep contemplation."}),"\n",(0,a.jsx)(n.p,{children:"A human life may be long or short, but those who live it brilliantly and meaningfully are not the majority."}),"\n",(0,a.jsx)(n.p,{children:"When someone is gone yet still remembered by so many \u2014 that person did not live in vain."}),"\n",(0,a.jsx)(n.p,{children:"Muzi \u2014 he has been gone a long time, but every day people still visit his blog, still leave comments. Over 70 million clicks record the admiration and longing of those who love him. His hearty, resonant laughter still echoes around us..."}),"\n",(0,a.jsx)(n.p,{children:"On the fifth day of the Lunar New Year this year, I left Beijing for a serene cemetery in Nanhai District, Foshan, Guangdong, to visit Muzi. He has been here for over two years now. Though I've never wanted to face the reality of his departure, it cannot be avoided \u2014 he simply cannot come back, and I had to go see him."}),"\n",(0,a.jsx)(n.p,{children:"Taking a taxi from Guangzhou proper, the driver didn't know the exact location we were heading to. Nanhai District is quite large, and the local Cantonese dialect was hard for me to understand. Guided by a motorbike taxi, we spent the better part of the morning before finally finding Changqing Cemetery. The vast cemetery grounds were impeccably maintained, so quiet it stopped all thought."}),"\n",(0,a.jsx)(n.p,{children:"Following the directions in Old Chen's text messages, we still couldn't find the specific spot. We had no choice but to go back to the administrative office, check the records, and finally locate Muzi's current home. Since all the shops in the surrounding area were closed for the New Year holiday, there was nowhere to buy offerings for the other world. Fortunately, the taxi driver who brought us was very kind \u2014 he patiently drove us around for half a day until we finally found one shop still open. After buying what we needed, he drove us up the hillside and waited below for us. I was deeply moved. Muzi's \"home\" perfectly suited his character \u2014 on a hillside with a wide-open view, flowing water circling the foot of the hill below."}),"\n",(0,a.jsx)(n.p,{children:"Winter in Guangdong is still green. The sun shone lazily, and everything around was peaceful and serene. Standing here, one cannot help but think about one's own life, one's own belonging. We set off a string of firecrackers to announce our arrival to Muzi \u2014 I imagine he knew. In silent communion with him, I wondered whether there's a stock market on the other side, and if not, what would keep him busy... What was most comforting was that he was together with his mother. He must be very happy now. Life truly came to an end here. But his image from those days \u2014 animated and vibrant, holding forth to us in that unstoppable torrent of words \u2014 remains vivid before my eyes. I remember very clearly asking him once: \"In this market, who's the best?\" He laughed his signature laugh and said: \"That would be us, of course.\" That confidence, that composure \u2014 no matter what state the market was in, he always had a definitive answer, never vague."}),"\n",(0,a.jsx)(n.p,{children:"How many people came to love our magazine because of his articles? Many acquaintances would ask me about his true identity, hoping to meet him in person and hear him speak. He was genuinely sincere with people and never concealed his views. A few sentences from him could clarify concepts that had been muddled in your head. What he showed us was always his most brilliant, most dazzling side. His own affairs he never discussed with us. Even in the final stage of his life, he still wished that we would forever remember only his most glorious face. He didn't want us to see him sick."}),"\n",(0,a.jsx)(n.p,{children:'In his final days, we stayed in touch by phone. I can still faintly hear him on the other end, his voice slurred and indistinct, murmuring again and again that he was fine, he was fine... He loved life so fiercely. He refused to believe that death could truly drag him away. On the day he left, he was in Guangzhou. Old Chen told us not to come, because he didn\'t want us there. Old Chen dressed him in his favorite silk Chinese-style changshan. He asked Old Chen to tell us \u2014 "He has gone wandering, and he will come back."'}),"\n",(0,a.jsx)(n.p,{children:"Coming to this place, accepting reality, only brought more reflection. I believe that when we meet again, Muzi will greet us with that characteristic, magnanimous laugh of his and tell us even more wonderful stories. So many people long to hear more of his stories. The articles he left on his blog \u2014 every single one is a classic."}),"\n",(0,a.jsx)(n.p,{children:"As the saying goes, Heaven envies genius. Perhaps in that other world he continues his story still. The stories he left behind in this world have become our eternal memories..."})]})}function c(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(96540);let a={},o=i.createContext(a);function s(e){let n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);